#[test]
fn pre_measurement_retry_is_bounded() {
    let mut campaign = BenchmarkCampaign::new("campaign-a", plan()).expect("campaign");
    assert!(campaign
        .record_pre_measurement_failure(0)
        .expect("retry one"));
    assert!(campaign
        .record_pre_measurement_failure(0)
        .expect("retry two"));
    assert!(!campaign
        .record_pre_measurement_failure(0)
        .expect("retry three"));
    assert_eq!(campaign.state, BenchmarkCampaignState::Stopped);
    assert_eq!(campaign.runs[0].status, CampaignRunStatus::Rejected);
    assert_eq!(
        campaign.runs[0].failure,
        Some(CampaignFailureKind::InfrastructurePreMeasurement)
    );
}
